import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"検索履歴","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 検索履歴（Search History）","slug":"_1-検索履歴-search-history","link":"#_1-検索履歴-search-history","children":[]},{"level":2,"title":"2. キーワード履歴（Keyword History）","slug":"_2-キーワード履歴-keyword-history","link":"#_2-キーワード履歴-keyword-history","children":[]},{"level":2,"title":"3. クエリ関連付け（Query Associations）","slug":"_3-クエリ関連付け-query-associations","link":"#_3-クエリ関連付け-query-associations","children":[]}],"relativePath":"ja-JP/user-guide/settings/history.md","filePath":"ja-JP/user-guide/settings/history.md","lastUpdated":1795268921000}`),a={name:`ja-JP/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="検索履歴" tabindex="-1">検索履歴 <a class="header-anchor" href="#検索履歴" aria-label="Permalink to “検索履歴”">​</a></h1><p>3つのタブで、開いた項目、検索語、クエリ関連をそれぞれ管理します。</p><h2 id="_1-検索履歴-search-history" tabindex="-1">1. 検索履歴（Search History） <a class="header-anchor" href="#_1-検索履歴-search-history" aria-label="Permalink to “1. 検索履歴（Search History）”">​</a></h2><p>検索結果から開いたファイル、フォルダー、アプリの回数と日時を記録します。</p><ul><li><strong>順位への反映</strong>：開くたびに1点を加え、上限は10点です。スコアは90日で半減します。有効スコア3でH3、5でH5の対象になります。クイック検索の枠はH5が3件、H3が10件、インライン検索は1件と3件です。フルウィンドウには件数枠がありません。</li><li><strong>順位を上げられる範囲</strong>：有効な一致等級と優先度が同じ結果の中で使用履歴を比較します。クイック検索の種類設定はファイル・フォルダーの完全一致等級にも影響します。<a href="./../search-syntax.html">検索構文</a>を参照してください。</li><li><strong>インライン表示</strong>：現在のフォルダーと全体の結果を分けて表示し、存在しないパスは省きます。</li><li><strong>管理</strong>：キーワードで絞り込み、個別削除、使用回数N以下の削除、全消去ができます。別のウィンドウから開くと一覧も更新されます。記録を無効にすると新規項目は追加されませんが、既存項目の回数と日時は更新されます。</li></ul><h2 id="_2-キーワード履歴-keyword-history" tabindex="-1">2. キーワード履歴（Keyword History） <a class="header-anchor" href="#_2-キーワード履歴-keyword-history" aria-label="Permalink to “2. キーワード履歴（Keyword History）”">​</a></h2><p>結果やアクションの実行時、またはフルウィンドウを開くときの元の検索語を保存します。入力してクイック検索を閉じるだけでは記録されません。</p><ul><li><strong>Alt+Up / Alt+Down</strong>で履歴を移動し、<strong>Ctrl+Delete</strong>で現在の項目を削除します。</li><li>絞り込み、個別削除、全消去、使用回数による削除ができます。独立した記録スイッチを無効にすると、新しい語は追加されず、既存語の回数だけが更新されます。</li></ul><h2 id="_3-クエリ関連付け-query-associations" tabindex="-1">3. クエリ関連付け（Query Associations） <a class="header-anchor" href="#_3-クエリ関連付け-query-associations" aria-label="Permalink to “3. クエリ関連付け（Query Associations）”">​</a></h2><p><strong>クエリ → 対象パス</strong>の関連を使用スコアとは別に保存します。</p><ul><li>同じ正規化クエリの通常の検索結果から対象を<strong>3回以上</strong>開くと、関連による補完が有効になります。学習した関連だけで表示された結果を開いても、この確認回数は増えません。</li><li>1回の検索で補完する関連は最大<strong>1件</strong>です。低優先度の対象は除外し、関連だけで見つかった結果は直接一致の後に表示します。</li><li>関連の絞り込み、個別削除、全消去をしても、パスの使用スコアは維持されます。</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};